# Verify adjective order against precedence evidenced in the 132-example list.
# Categories are assigned per word; pairwise precedence is taken only from
# co-occurrences in the examples, then closed transitively.

CATS = {}
def add(cat, words):
    for w in words.split():
        CATS[w] = cat

add('opinion', 'awful silly terrible wonderful obnoxious ridiculous repulsive mysterious good nice lovely')
add('origin', 'japanese american russian indonesian iranian filipino indian ethiopian bangladeshi german turkish chinese vietnamese brazilian pakistani congolese mexican')
add('size', 'big small tiny little huge large massive enormous medium-size midsize normal-size')
add('color', 'green crimson maroon aqua white yellow brown cyan teal magenta violet gray red black blue indigo')
add('age', 'new old ancient archaic brand-new old-fashioned')
add('shape', 'circular square rectangular triangular pyramidal prismlike spherical')
add('purpose', 'smoking exercise driving drinking walking hiking eating snorkeling whittling')
add('material', 'leather wool paper steel iron wood cardboard glass fiberglass plastic canvas')

# Pairs observed directly in the examples (first must precede second).
# Material-vs-color/age/shape/purpose and opinion-vs-purpose never co-occur, so they stay unknown.
OBS = {('origin', 'size'), ('size', 'color'), ('color', 'age'),
       ('age', 'shape'), ('shape', 'purpose'), ('opinion', 'material')}

def closure(rel):
    c = set(rel)
    changed = True
    while changed:
        changed = False
        for (a, b) in list(c):
            for (x, y) in list(c):
                if b == x and (a, y) not in c:
                    c.add((a, y))
                    changed = True
    return c

PREC = closure(OBS)

def rel(a, b):
    if a == b or (a, b) in PREC:
        return 'ok'
    if (b, a) in PREC:
        return 'bad'
    return 'unk'

OPTIONS = {
    'A': 'awful leather violet ancient rectangular whittling plate',
    'B': 'maroon old square exercise cardboard obnoxious fire extinguisher',
    'C': 'little gray old triangular driving wood wonderful apple',
    'D': 'congolese enormous green brand-new pyramidal hiking steel terrible guitar',
    'E': 'steel terrible gray new triangular hiking small canvas',
    'F': 'wool good indigo old square hiking little mexican watch',
    'G': 'repulsive indigo brand-new prismlike drinking enormous filipino piano',
    'H': 'pakistani tiny cyan brand-new rectangular exercise mysterious fiberglass bottle',
    'I': 'wool teal new rectangular hiking massive ethiopian ring',
    'J': 'iranian massive blue old spherical snorkeling chair',
}

def judge(text):
    seq = []
    for t in text.split():
        if t not in CATS:
            break  # first non-adjective token starts the noun phrase
        seq.append((t, CATS[t]))
    verdict = 'PASS'
    for i in range(len(seq)):
        for j in range(i + 1, len(seq)):
            r = rel(seq[i][1], seq[j][1])
            if r == 'bad':
                return 'FAIL', (seq[i][0], seq[j][0])
            if r == 'unk':
                verdict = 'UNKNOWN'
    return verdict, None

results = {k: judge(v) for k, v in OPTIONS.items()}
for k, (v, witness) in results.items():
    tag = {'PASS': 'CHECK PASS', 'FAIL': 'CHECK FAIL', 'UNKNOWN': 'CHECK UNKNOWN'}[v]
    extra = f' violating pair {witness}' if witness else ''
    print(f'{k}: {tag}{extra}')

passes = [k for k, (v, _) in results.items() if v == 'PASS']
unknown = [k for k, (v, _) in results.items() if v == 'UNKNOWN']

# J is fully determined by observed precedence; A and H depend on pairs the list never shows.
if passes and not unknown:
    print('ANSWER', ''.join(passes))
elif not passes and not unknown:
    print('ANSWER K')
else:
    print('UNSUPPORTED for full selection: undecided options', unknown,
          '; options confirmed correct:', passes)
